//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Values below one are
    /// treated as one attempt by `run_job`.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Creates a retry configuration.
    pub const fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        Self {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn constructor_preserves_policy_settings() {
        assert_eq!(
            RetryConfig::new(4, 25, 100),
            RetryConfig {
                max_attempts: 4,
                base_delay_ms: 25,
                max_delay_ms: 100,
            }
        );
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempts = 0;
    let mut delay_ms = config.base_delay_ms.min(config.max_delay_ms);

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempts < max_attempts => {
                sleeper.sleep_ms(delay_ms);
                delay_ms = delay_ms.saturating_mul(2).min(config.max_delay_ms);
            }
            Err(error) => return Err(error),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let config = RetryConfig::new(5, 10, 25);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            if calls < 4 {
                Err(RetryError::Transient("try again".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let config = RetryConfig::new(4, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("bad input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn attempt_budget_includes_first_call() {
        let config = RetryConfig::new(3, 1, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("still down".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("still down".into())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![1, 2]);
    }

    #[test]
    fn zero_attempt_budget_still_makes_one_call() {
        let config = RetryConfig::new(0, 10, 100);
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let _ = run_job(&config, &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("temporary".into()))
        });

        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }
}

//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::RetryError;

    #[test]
    fn only_transient_errors_are_retryable() {
        assert!(RetryError::Transient("temporary".into()).is_transient());
        assert!(!RetryError::Permanent("invalid".into()).is_transient());
    }
}

# jobrunner

Small job runner with a pluggable, bounded exponential retry policy.

## Retry policy

`RetryConfig::new(max_attempts, base_delay_ms, max_delay_ms)` configures the
runner. `max_attempts` is the total number of calls, including the first call;
values below one still permit one call. A failed transient attempt is followed
by a delay before the next attempt. Delays start at `base_delay_ms`, double
after each retry, and saturate at `max_delay_ms`. The injected `Sleeper` makes
delays testable without waiting.

Only `RetryError::Transient` failures are retried. `RetryError::Permanent`
failures return immediately, and the final error is returned when the attempt
budget is exhausted. A successful attempt returns immediately.

```rust
use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

let config = RetryConfig::new(4, 50, 500);
let mut sleeper = FakeSleeper::default();
let mut attempts = 0;

let result = run_job(&config, &mut sleeper, || {
    attempts += 1;
    if attempts < 3 {
        Err(RetryError::Transient("temporary outage".into()))
    } else {
        Ok(())
    }
});

assert!(result.is_ok());
assert_eq!(sleeper.sleeps, vec![50, 100]);
```

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_runner_retries_transient_failures_and_returns_success() {
    let config = RetryConfig::new(4, 5, 12);
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        match attempts {
            1 | 2 => Err(RetryError::Transient("temporary".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 3);
    assert_eq!(sleeper.sleeps, vec![5, 10]);
}

#[test]
fn public_runner_does_not_retry_permanent_failures() {
    let config = RetryConfig::new(10, 1, 100);
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&config, &mut sleeper, || {
        attempts += 1;
        Err(RetryError::Permanent("invalid job".into()))
    });

    assert_eq!(result, Err(RetryError::Permanent("invalid job".into())));
    assert_eq!(attempts, 1);
    assert!(sleeper.sleeps.is_empty());
}

//! Harness-owned behavioral oracle; copied in by the evaluation harness
//! after the run. Not authored by the evaluated agent.

use jobrunner::{FakeSleeper, RetryConfig, RetryError, Sleeper};

fn config(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> RetryConfig {
    RetryConfig {
        max_attempts,
        base_delay_ms,
        max_delay_ms,
    }
}

#[test]
fn first_try_success_never_waits() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0u32;
    let result = jobrunner::run_job(&config(3, 25, 100), &mut sleeper, || {
        calls += 1;
        Ok(())
    });
    assert!(result.is_ok());
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn transient_errors_are_retried_until_success() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0u32;
    let result = jobrunner::run_job(&config(5, 10, 500), &mut sleeper, || {
        calls += 1;
        if calls < 4 {
            Err(RetryError::Transient("blip".into()))
        } else {
            Ok(())
        }
    });
    assert!(result.is_ok(), "transient faults must be retried to success");
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps.len(), 3, "one wait per retry");
}

#[test]
fn permanent_errors_return_without_waiting() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0u32;
    let result = jobrunner::run_job(&config(9, 10, 500), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("bad input".into()))
    });
    assert!(matches!(result, Err(RetryError::Permanent(_))));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}

#[test]
fn max_attempts_includes_the_first_call() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0u32;
    let result = jobrunner::run_job(&config(1, 10, 100), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("blip".into()))
    });
    assert!(result.is_err());
    assert_eq!(calls, 1, "one attempt means no retry");
    assert!(sleeper.sleeps.is_empty());

    let mut calls = 0u32;
    let mut sleeper = FakeSleeper::default();
    let _ = jobrunner::run_job(&config(4, 10, 100), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("blip".into()))
    });
    assert_eq!(calls, 4, "the budget caps total attempts including the first");
    assert_eq!(sleeper.sleeps.len(), 3);
}

#[test]
fn delays_grow_monotonic_and_saturate_at_max_delay_ms() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0u32;
    let _ = jobrunner::run_job(&config(6, 50, 400), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("blip".into()))
    });
    assert_eq!(calls, 6);
    let sleeps = &sleeper.sleeps;
    assert_eq!(sleeps.len(), 5);
    for delay in sleeps {
        assert!(*delay >= 1, "a nonzero base delay must produce a wait");
        assert!(*delay <= 400, "delays saturate at max_delay_ms");
    }
    for pair in sleeps.windows(2) {
        assert!(pair[0] <= pair[1], "exponential growth must not shrink");
    }
}

#[test]
fn huge_base_delays_saturate_instead_of_overflowing() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0u32;
    let _ = jobrunner::run_job(&config(4, u64::MAX, 250), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("blip".into()))
    });
    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps.len(), 3);
    for delay in &sleeper.sleeps {
        assert_eq!(
            *delay, 250,
            "a base above the cap must saturate at max_delay_ms"
        );
    }
}

#[test]
fn public_api_accepts_a_dyn_sleeper() {
    let mut sleeper = FakeSleeper::default();
    let dyn_sleeper: &mut dyn Sleeper = &mut sleeper;
    let result =
        jobrunner::run_job(&config(2, 5, 50), dyn_sleeper, || {
            Err(RetryError::Transient("once".into()))
        });
    assert!(result.is_err());
}
